import json,pathlib
R=pathlib.Path(__file__).resolve().parent
a=json.load(open(R/'source-analysis.json'))
def check(paths,details):return {'status':'passed','evidence_paths':paths,'details':details}
r={'verdict':'accepted','summary':'Both retained defects are repaired. All eight checks pass on independent source replay, boundary and fresh samples, the exact batch, native grading and actual UI rendering. Package unchanged; no publication or database writes.',
 'source_analysis':{k:a[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs']},
 'checks':{
 'source_replay':check(['source-confirmation.json','source-replay-results.json','source-replay-records.json','repair-verification.json','retained-failing-example.json','retained-current-results.json'],'All eight supplied questions replay with matching prompts, field contracts, complete ordered banks, available keys and solutions. Source-index replay survives reordered traversal. Canonical 3.25 classification verified. Missing legacy sqrt(121) key/solution and canonical answer bank are documented; their captured absence is preserved.'),
 'math':check(['math-results.json','negative-domain-results.json','negative-records.json','controlled-records.json'],'221 generated records independently checked from displayed values using exact rational arithmetic and square tests. All 144 supported negative radicands have mathematically correct visible imaginary coefficients and C-only membership.'),
 'variety':check(['coverage-results.json','sampling-trace.json','negative-domain-results.json','inventory-analysis.json','affected-inventory.json'],'Fresh sample seed 731905 covers every membership class and all five representations. Construction and sampling support every negative radicand -144..-1. Fifty proposals yield 40 distinct records; 38 survive delivery with all five classes. Retained coverage defects have no demonstrated affected stored instances in captured inventory.'),
 'scope':check(['scope-results.json','source-analysis.json','sample-records.json','controlled-records.json'],'Changed negative nonsquare roots are directly source-supported. Observed outputs preserve easy single-number classification, elementary simplification, five basic sets and source response workload.'),
 'grading':check(['grader-input.json','grader-results.json','counterfactual-results.json'],'Native database-free grader returned 1112 expected acceptances and 1108 expected rejections, with no unresolved checks. Both checkbox values and every radio alternative exercised. Controlled pairs cross-submit prior responses against changed evidence. No free-entry fields exist.'),
 'rendering':check(['render/rendering.json','render-records.json','visual-inspection.json','render/question-001.png','render/question-008.png','render/question-014.png','render/question-015.png'],'Actual unmodified UI rendered 15 records without reported errors. Screenshots inspected for changed roots, controlled fractions, all three radio banks, answer controls, hierarchy image and worked solutions.'),
 'packaging':check(['packaging-results.json','package-before.json','package-after.json','repair-verification.json','commands.md'],'Exact installed Python 3.13.5 matches the manifest; dependencies are standard-library only. Declared-file relocation and deterministic replay pass. Invalid difficulty/count and bounded duplicate exhaustion reject appropriately. Recursive package hashes remain unchanged.'),
 'decision_variation':check(['pedagogical-variation.json','counterfactual-results.json','shortcut-results.json','coverage-results.json','sampling-trace.json','selection-results.json','delivery-transformation-results.json','delivery-batch/delivery.json','delivery-sample/delivery.json','evidence-validation.json'],'Relevant and irrelevant controlled changes agree with displayed prompts, explanations, actual grading and screenshots. Conditional label, count and positional probes found no incidental complete-answer bypass. Exact batch 5->4 retains C=1, NZQRC=2, RC=1; fresh sample 40->38 retains all five masks. Selection examined using actual rules and explicit no-history, prefix and leave-one scenarios. Live policy/history and future inventory are unknown; conclusions are conditional, not an assertion of exhaustive shortcut absence.')},
 'findings':[]}
r['source_analysis']['evidence_paths']=['source-analysis.json','source-confirmation.json']
for v in r['checks'].values():
 for p in v['evidence_paths']:assert (R/p).is_file() and (R/p).stat().st_size>0,p
(R/'result.json').write_text(json.dumps(r,indent=2,ensure_ascii=False))
print(json.dumps({'verdict':r['verdict'],'checks':list(r['checks']),'result_file':'result.json','findings':0}))
